-- Broader US-market Explore catalog and clothing-category filters.
alter table public.explore_outfits drop constraint explore_outfits_category_check,
  add constraint explore_outfits_category_check check(category in (
    'Tops','Shirts','Hoodies','Jackets','Bottoms','Dresses','Shoes','Accessories','Other',
    'Denim','Knitwear','Skirts','Shorts','Swimwear'
  ));

-- Keep the existing RPC signature so older app builds continue to paginate.
create or replace function public.explore_page(
  search_text text default '', style_filter text default '',
  after_rank integer default -1, page_size integer default 12
) returns setof public.explore_outfits
language sql stable security invoker set search_path='' as $$
 select * from public.explore_outfits
 where published and rank > after_rank
   and (style_filter='' or style=style_filter or category=style_filter)
   and (trim(search_text)='' or strpos(
     lower(name || ' ' || brand || ' ' || tags || ' ' || category),
     lower(left(trim(search_text),100))
   )>0)
 order by rank limit greatest(1,least(page_size,40))
$$;

-- Public US-market product catalog, captured 2026-11-20.
do $$ declare offset_rank integer; begin select coalesce(max(rank),0)+10000 into offset_rank from public.explore_outfits; update public.explore_outfits set rank=rank+offset_rank; end $$;
update public.explore_outfits set published=false where photo_url is not null;
on conflict(id) do update set name=excluded.name,style=excluded.style,category=excluded.category,description=excluded.description,source_label=excluded.source_label,tags=excluded.tags,photo_url=excluded.photo_url,price_label=excluded.price_label,source_url=excluded.source_url,rank=excluded.rank,published=true;
